-- Alpha Capitalis: Politika privatnosti i Uvjeti korištenja
-- Namijenjeno ručnom uvozu kroz phpMyAdmin (MySQL/MariaDB).
-- Skripta je idempotentna: postojeće zapise ažurira, a nedostajuće dodaje.
-- Ne upisuje ništa u Laravelovu tablicu `migrations`.

SET NAMES utf8mb4 COLLATE utf8mb4_unicode_ci;
START TRANSACTION;

SET @privacy_html = CONVERT(FROM_BASE64('') USING utf8mb4);
SET @terms_html = CONVERT(FROM_BASE64('') USING utf8mb4);

-- Politika privatnosti: prednost ima postojeći zapis s kodom privacy-policy,
-- a zatim zapis povezan s hrvatskim slugom politika-privatnosti.
SET @privacy_page_id = (
    SELECT `id`
    FROM `content_info_pages`
    WHERE `code` = 'privacy-policy'
    LIMIT 1
);

SET @privacy_page_id = COALESCE(
    @privacy_page_id,
    (
        SELECT `page_id`
        FROM `content_info_page_translations`
        WHERE `locale` = 'hr'
          AND `slug` = 'politika-privatnosti'
        LIMIT 1
    )
);

INSERT INTO `content_info_pages` (
    `code`, `layout`, `is_active`, `show_in_footer`, `published_at`,
    `sort_order`, `payload`, `created_by`, `updated_by`, `created_at`, `updated_at`
)
SELECT
    'privacy-policy', 'legal', 1, 1, NOW(),
    90, NULL, NULL, NULL, NOW(), NOW()
WHERE @privacy_page_id IS NULL;

SET @privacy_page_id = COALESCE(@privacy_page_id, LAST_INSERT_ID());

UPDATE `content_info_pages`
SET `code` = 'privacy-policy',
    `layout` = 'legal',
    `is_active` = 1,
    `show_in_footer` = 1,
    `published_at` = NOW(),
    `sort_order` = 90,
    `payload` = NULL,
    `updated_at` = NOW()
WHERE `id` = @privacy_page_id;

UPDATE `content_info_page_translations`
SET `title` = 'Politika privatnosti',
    `slug` = 'politika-privatnosti',
    `excerpt` = 'Kako Alpha Capitalis prikuplja, koristi, čuva i štiti osobne podatke.',
    `body_html` = @privacy_html,
    `meta_title` = 'Politika privatnosti | Alpha Capitalis',
    `meta_description` = 'Saznajte koje osobne podatke Alpha Capitalis obrađuje, u koje svrhe, na kojim pravnim osnovama i koja prava imate.',
    `payload` = NULL,
    `updated_at` = NOW()
WHERE `page_id` = @privacy_page_id
  AND `locale` = 'hr';

INSERT INTO `content_info_page_translations` (
    `page_id`, `locale`, `title`, `slug`, `excerpt`, `body_html`,
    `meta_title`, `meta_description`, `payload`, `created_at`, `updated_at`
)
SELECT
    @privacy_page_id,
    'hr',
    'Politika privatnosti',
    'politika-privatnosti',
    'Kako Alpha Capitalis prikuplja, koristi, čuva i štiti osobne podatke.',
    @privacy_html,
    'Politika privatnosti | Alpha Capitalis',
    'Saznajte koje osobne podatke Alpha Capitalis obrađuje, u koje svrhe, na kojim pravnim osnovama i koja prava imate.',
    NULL,
    NOW(),
    NOW()
WHERE NOT EXISTS (
    SELECT 1
    FROM `content_info_page_translations`
    WHERE `page_id` = @privacy_page_id
      AND `locale` = 'hr'
);

-- Uvjeti korištenja.
SET @terms_page_id = (
    SELECT `id`
    FROM `content_info_pages`
    WHERE `code` = 'terms-of-use'
    LIMIT 1
);

SET @terms_page_id = COALESCE(
    @terms_page_id,
    (
        SELECT `page_id`
        FROM `content_info_page_translations`
        WHERE `locale` = 'hr'
          AND `slug` = 'uvjeti-koristenja'
        LIMIT 1
    )
);

INSERT INTO `content_info_pages` (
    `code`, `layout`, `is_active`, `show_in_footer`, `published_at`,
    `sort_order`, `payload`, `created_by`, `updated_by`, `created_at`, `updated_at`
)
SELECT
    'terms-of-use', 'legal', 1, 1, NOW(),
    91, NULL, NULL, NULL, NOW(), NOW()
WHERE @terms_page_id IS NULL;

SET @terms_page_id = COALESCE(@terms_page_id, LAST_INSERT_ID());

UPDATE `content_info_pages`
SET `code` = 'terms-of-use',
    `layout` = 'legal',
    `is_active` = 1,
    `show_in_footer` = 1,
    `published_at` = NOW(),
    `sort_order` = 91,
    `payload` = NULL,
    `updated_at` = NOW()
WHERE `id` = @terms_page_id;

UPDATE `content_info_page_translations`
SET `title` = 'Uvjeti korištenja',
    `slug` = 'uvjeti-koristenja',
    `excerpt` = 'Pravila pristupa i korištenja internetske stranice Alpha Capitalis.',
    `body_html` = @terms_html,
    `meta_title` = 'Uvjeti korištenja | Alpha Capitalis',
    `meta_description` = 'Uvjeti pristupa i korištenja sadržaja, obrazaca i drugih funkcionalnosti internetske stranice Alpha Capitalis.',
    `payload` = NULL,
    `updated_at` = NOW()
WHERE `page_id` = @terms_page_id
  AND `locale` = 'hr';

INSERT INTO `content_info_page_translations` (
    `page_id`, `locale`, `title`, `slug`, `excerpt`, `body_html`,
    `meta_title`, `meta_description`, `payload`, `created_at`, `updated_at`
)
SELECT
    @terms_page_id,
    'hr',
    'Uvjeti korištenja',
    'uvjeti-koristenja',
    'Pravila pristupa i korištenja internetske stranice Alpha Capitalis.',
    @terms_html,
    'Uvjeti korištenja | Alpha Capitalis',
    'Uvjeti pristupa i korištenja sadržaja, obrazaca i drugih funkcionalnosti internetske stranice Alpha Capitalis.',
    NULL,
    NOW(),
    NOW()
WHERE NOT EXISTS (
    SELECT 1
    FROM `content_info_page_translations`
    WHERE `page_id` = @terms_page_id
      AND `locale` = 'hr'
);

COMMIT;

-- Očekivani rezultat: dva reda, oba aktivna i vidljiva u footeru.
SELECT
    p.`id`, p.`code`, p.`layout`, p.`is_active`, p.`show_in_footer`,
    t.`locale`, t.`title`, t.`slug`
FROM `content_info_pages` AS p
INNER JOIN `content_info_page_translations` AS t ON t.`page_id` = p.`id`
WHERE p.`code` IN ('privacy-policy', 'terms-of-use')
  AND t.`locale` = 'hr'
ORDER BY p.`sort_order`;
